content.css:
.cslanding-page-header {
  display: flex;
  flex-direction: column;
  align-items: center;
}
.cslanding-page-wrapper {
  display: flex;
  flex-direction: column;
  height: 100%;
  justify-content: center;
}
.cslanding-page-slideshow-container {
  display: flex;
  align-items: center;
  justify-content: center;
}
.cslanding-page-sliderImage {
  width: 120%;
}
.cslanding-page-slideCaption,
.cslanding-page-dotContainers {
  text-align: center;
  padding-top: 5px;
}
.cslanding-page-dotSpan {
  cursor: pointer;
  height: 10px;
  width: 10px;
  margin: 0 7px;
  background-color: transparent;
  border: 1px solid #666666;
  border-radius: 50%;
  display: inline-block;
  transition: background-color 0.6s ease;
}
.cflanding-page-active,
.cflanding-page-dotSpan:hover {
  background-color: #333333;
  border: 1px solid #333333;
}
.cslanding-page-button {
  outline: none;
  text-align: center;
  padding: 8px 12px 8px 12px;
  font-size: 1em;
  box-sizing: border-box;
  display: flex;
  align-items: center;
  justify-content: center;
  text-decoration: none !important;
  color: #000 !important;
  min-width: 130px;
}
.bg-yellow {
  background: #f2c811;
}
.cslanding-page-footerDiv {
  display: flex;
  justify-content: center;
  margin-top: 14px;
}
.cslanding-page-slideImageWrapper {
  display: flex;
  font-family: "FabricMDL2Icons";
  margin-top: 10px;
}
/*
  Your use of the content in the files referenced here is subject to the terms of the license at https://aka.ms/fabric-assets-license
*/
@font-face {
  font-family: "FabricMDL2Icons";
  src: url("data:application/octet-stream;base64,") format("truetype");
}
.ms-Icon {
  -moz-osx-font-smoothing: grayscale;
  -webkit-font-smoothing: antialiased;
  display: inline-block;
  font-family: "FabricMDL2Icons";
  font-style: normal;
  font-weight: normal;
  speak: none;
}
.ms-Icon--ChevronLeftMed:before {
  content: "\E973";
}
.ms-Icon--ChevronRightMed:before {
  content: "\E974";
}
.cslanding-page-prev,
.cslanding-page-next {
  display: flex;
  align-items: center;
  font-size: 25px;
  color: #c8c8c8;
}
.cslanding-page-prev span {
  padding-right: 13px;
}
.cslanding-page-next span {
  padding-left: 13px;
}
.cslanding-page-active,
.cslanding-page-dotSpan:hover {
  background-color: #333333;
}
.cslanding-page-title,
.cslanding-page-subtitle,
.cslanding-page-slideCaption {
  font-family: Segoe UI;
  font-style: normal;
  text-align: center;
  color: #333333;
}
.cslanding-page-title {
  font-weight: 300;
  font-size: 32px;
  margin-bottom: 24px;
}
.cslanding-page-subtitle {
  font-weight: bold;
  font-size: 22px;
}
